/* Story language */
.reader-tools { display:flex; align-items:center; gap:12px; flex-wrap:wrap; justify-content:flex-end; }
.language-picker { display:inline-flex; align-items:center; gap:8px; font-size:12px; color:var(--muted); }
.language-picker select { font:inherit; color:var(--ink); background:#fffdf8; border:1px solid var(--line); border-radius:8px; padding:8px 10px; }
.language-picker select:disabled { opacity:.6; }
.chat-card .language-picker { display:flex; justify-content:flex-end; margin-bottom:12px; }

/* Read-along highlighting */
.narration .word { border-radius:4px; transition:background-color .12s ease, color .12s ease; }
.narration .reading-word { background:#f6dfa9; color:var(--ink); box-shadow:0 0 0 2px #f6dfa9; }

/* Phonics */
.narration .word.tappable { font:inherit; color:inherit; background:none; border:0; padding:0; margin:0; cursor:pointer; text-decoration:underline dotted #c9b98f; text-underline-offset:5px; }
.narration .word.tappable:hover, .narration .word.tappable:focus-visible { background:#efe6cc; }
.narration .word.tappable.reading-word { background:#f6dfa9; }
.phonics-card { width:100%; border:1px solid var(--line); background:#fff8ea; border-radius:14px; padding:18px 20px; margin-bottom:18px; }
.phonics-card .eyebrow { margin-bottom:12px; }
.phonics-parts { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:16px; }
.phonics-part { font:600 34px/1.2 Georgia,serif; padding:6px 14px; border-radius:10px; background:#f1ecdc; color:var(--muted); transition:all .15s ease; }
.phonics-part.lit { background:var(--orange); color:white; transform:translateY(-2px); }
.phonics-actions { display:flex; gap:10px; flex-wrap:wrap; }

